function buildDeck(seeds: Record<SourceGame, Seed[]>, playMode: PlayMode): PromptItem[] {
  return (Object.entries(seeds) as [SourceGame, Seed[]][]).flatMap(([gameId, cards]) => cards.map((card, index) => ({
    id: `unh-v2-${playMode}-${gameId}-${index + 1}`,
    gameId, category: 'unhinged' as const, playMode, ...card,
    ...(gameId === 'truth-or-sip' ? { forfeit: 'Take a sip of any drink, or pass.' } : {}),
  })));
}

export const UNHINGED_PROMPTS = buildDeck(IN_PERSON, 'in-person');
export const ONLINE_UNHINGED_PROMPTS = buildDeck(ONLINE, 'online');

const rare = (id: string, gameId: SourceGame, playMode: PlayMode, text: string, type?: 'truth' | 'dare'): PromptItem => ({
  id, gameId, category: 'unhinged', playMode, text, ...(type ? { type } : {}),
  isLegendary: true, rarity: 'legendary', legendaryTitle: 'LEGENDARY REPUTATION DAMAGE',
});

